{
 "type": "object",
 "required": [
 "TrustFramework"
 ],
 "properties": {
 "TrustFramework": {
 "$ref": "#/components/schemas/TrustFrameworkCode"
 },
 "AssuranceLevel": {
 "type": "string",
 "description": "Determines the assurance level associated with the User in the respective VerifiedClaims. The value range depends on the respective TrustFramework value.\nAssurance Level: [https://bitbucket.org/openid/ekyc-ida/wiki/identifiers](https://bitbucket.org/openid/ekyc-ida/wiki/identifiers)\n"
 },
 "AssuranceProcess": {
 "$ref": "#/components/schemas/AssuranceProcess"
 },
 "Time": {
 "anyOf": [
 {
 "$ref": "#/components/schemas/ISODateTime"
 }
 ],
 "description": "Representing the date and time when the identity verification process took place. All dates in the JSON payloads are represented in ISO 8601 date-time format. All date-time fields in responses must include the timezone. An example is below: 2017-04-05T10:43:07+00:00\n"
 },
 "VerificationProcess": {
 "type": "string",
 "description": "Unique reference to the identity verification process as performed by the OP. Used for identifying and retrieving details in case of disputes or audits. Presence of this element might be required for certain trust frameworks.\n"
 },
 "Evidence": {
 "description": "The type of evidence allowed for providing verification.\nOpenID Connect for Identity Assurance 1.0: [https://openid.net/specs/openid-connect-4-identity-assurance-1_0.html#name-evidence-element](https://openid.net/specs/openid-connect-4-identity-assurance-1_0.html#name-evidence-element)\n",
 "anyOf": [
 {
 "$ref": "#/components/schemas/AEPartyIdentityEvidenceTypeDocument"
 },
 {
 "$ref": "#/components/schemas/AEPartyIdentityEvidenceTypeElectronicRecord"
 }
 ]
 }
 },
 "description": "Verification\n[https://openid.net/specs/openid-connect-4-identity-assurance-1_0.html#name-verification-element](https://openid.net/specs/openid-connect-4-identity-assurance-1_0.html#name-verification-element)\n",
 "additionalProperties": false
}

Get Customer for an Account > OpenAPI definition #/components/schemas/TrustFrameworkCode

{
 "type": "string",
 "enum": [
 "FI"
 ],
 "description": "Identifies the trust framework used for verification. This consists of a set of rules and standards and sets out requirements so that organisations know what ‘good’ identity verification looks like.\n\nPermitted values:\n\n* `FI` — the LFI (Financial Institution) has carried out verification of the customer details based on its own processes adhering to UAE legislation for KYC and AML.\n\nMirrors `CbuaeVerifiedClaim.verification.trustFramework` in the Ozone Connect Bank Data Sharing API so that the value emitted by an LFI can be passed through to the TPP-facing surface without translation.\n\nTrust Frameworks: [https://bitbucket.org/openid/ekyc-ida/wiki/identifiers](https://bitbucket.org/openid/ekyc-ida/wiki/identifiers)"
}

